#define PUNKTFUNK_MSG_CLOCK_PROBE 48

#define PUNKTFUNK_MSG_CLOCK_ECHO 49

#define PUNKTFUNK_MSG_PHASE_REPORT 50

// Idempotent enable/disable. Opt-in is here, not just in UI.
