// What produced the distance. `flags` low byte.
typedef enum {
    // Source not reported; treated as detent-counted wheel units.
    PUNKTFUNK_SCROLL_SOURCE_UNKNOWN = 0,
    // Notched wheel; `delta` is Q24.8 v120.
    PUNKTFUNK_SCROLL_SOURCE_WHEEL = 1,
    // Finger on a touchpad or similar; `delta` is Q24.8 DIP.
    PUNKTFUNK_SCROLL_SOURCE_FINGER = 2,
    // Continuous surface without finger tracking (dial, tilt wheel).
    PUNKTFUNK_SCROLL_SOURCE_CONTINUOUS = 3,
    // Touchscreen pan; `delta` is Q24.8 DIP.
    PUNKTFUNK_SCROLL_SOURCE_TOUCH = 4,
    // Controller-driven scroll (stick, gyro, touchpad emulation).
    PUNKTFUNK_SCROLL_SOURCE_CONTROLLER = 5,
} PunktfunkScrollSource;

// Gesture boundary marker. `flags` bits 8–15.
typedef enum {
    // No boundary — a plain delta (the only phase wheel sources may send).
    PUNKTFUNK_SCROLL_PHASE_NONE = 0,
    // Gesture starts; may carry its first delta.
    PUNKTFUNK_SCROLL_PHASE_BEGIN = 1,
    // Gesture delta.
    PUNKTFUNK_SCROLL_PHASE_UPDATE = 2,
    // Gesture ends; `delta` must be 0.
    PUNKTFUNK_SCROLL_PHASE_END = 3,
    // Gesture cancelled; `delta` must be 0.
    PUNKTFUNK_SCROLL_PHASE_CANCEL = 4,
    // Client-computed kinetic tail starts after the gesture's `End`.
    PUNKTFUNK_SCROLL_PHASE_MOMENTUM_BEGIN = 5,
    // Kinetic delta.
    PUNKTFUNK_SCROLL_PHASE_MOMENTUM = 6,
    // Kinetic tail ends; `delta` must be 0.
    PUNKTFUNK_SCROLL_PHASE_MOMENTUM_END = 7,
} PunktfunkScrollPhase;

// The receiver half of reactive recovery: an AU reaches the decoder only when every picture
// it references was decoded. After an index gap, each AU until the host's IDR or anchor names
// the lost picture. A wave start also ends the stretch on a lenient decoder; a strict one keeps
// withholding and asks for a keyframe. One per elementary stream, fed every AU in receive
// order. A withheld AU is never fed and never folded into [`ReanchorGate`]; the gate's
// [`REANCHOR_FREEZE_MAX`] re-ask ends a stretch whose anchor was lost.
typedef struct AuAdmission AuAdmission;

// Per-session CICP (ITU-T H.273) the host resolved, on [`Welcome`]. Configure the
// decoder/presenter from these; do not infer from bitstream VUI. An older host omits the
// bytes → [`ColorInfo::SDR_BT709`]. ST.2086 + CLL can change mid-stream, so they ride
// [`HDR_META_MAGIC`] rather than this fixed struct.
typedef struct ColorInfo ColorInfo;

// Tuning for [`JitterPolicy`], in milliseconds. Depth is time, not device quanta: `3 × quantum`
// is 15 ms at 5 ms and 64 ms at 20 ms.
typedef struct JitterTuning JitterTuning;

// Local bitstream-parser view of intra-refresh recovery on one frame — the in-band counterpart
// of [`USER_FLAG_RECOVERY_POINT`](crate::packet::USER_FLAG_RECOVERY_POINT). Two facts, not one
// verdict: a recovery-point SEI promises a correct picture N frames later for a decoder that
// lost references *before* the SEI, and nothing for a loss *after* it. Only
// [`ReanchorGate::on_local_recovery`] pairs the SEI against the arm, because only the gate
// knows when the loss was. Lanes without a parser leave this [`Default`].
typedef struct LocalRecovery LocalRecovery;

#if defined(PUNKTFUNK_FEATURE_QUIC)
// Live `punktfunk/1` connection (QUIC control + UDP data, pumped on internal threads).
// One puller thread per plane; never two threads on the same plane.
typedef struct PunktfunkConnection PunktfunkConnection;
#endif

#if defined(PUNKTFUNK_FEATURE_QUIC)
// A running demo host from [`punktfunk_demo_host_start`].
typedef struct PunktfunkDemoHost PunktfunkDemoHost;
#endif

// Opaque handle: one elementary stream's [`H265Concealer`]. The type lives in another crate,
// so the header needs a core-owned name for it.
typedef struct PunktfunkH265Concealer PunktfunkH265Concealer;

// Opaque session handle. C sees only the pointer.
typedef struct PunktfunkSession PunktfunkSession;

// Shared post-loss freeze. A client feeds *arm* (loss), each decoded frame
// ([`on_decoded`](Self::on_decoded)), each no-output AU ([`on_no_output`](Self::on_no_output)),
// and a periodic [`poll`](Self::poll). The gate emits *intents* only: `true` means the client
// should ask for a keyframe through its own ~100 ms throttle. The gate never touches the wire.
typedef struct ReanchorGate ReanchorGate;

// Log sink for [`punktfunk_set_log_callback`]. `level` 1..=5 (error…trace).
// `target` and `message` are NUL-terminated UTF-8, borrowed for this call —
// copy them out. Any thread may call; thread-safe, non-blocking, no re-entry.
typedef void (*PunktfunkLogCb)(uint8_t level, const char *target, const char *message, void *user);

// Session configuration. Set `struct_size` to `sizeof(PunktfunkConfig)`; a
// smaller prefix is rejected rather than over-read.
typedef struct {
    uint32_t struct_size;
    // 0 = host, 1 = client.
    uint32_t role;
    // 1 = P1 (GameStream-compatible), 2 = P2 (`punktfunk/1`).
    uint32_t phase;
    // 0 = GF(2⁸), 1 = GF(2¹⁶).
    uint32_t fec_scheme;
    uint32_t fec_percent;
    uint32_t max_data_per_block;
    uint32_t shard_payload;
    // Non-zero enables AES-128-GCM.
    uint32_t encrypt;
    uint8_t key[16];
    uint8_t salt[4];
    // Test hook for the loopback transport; 0 in production.
    uint32_t loopback_drop_period;
    // Largest encoded access unit the receiver accepts (reassembler memory bound).
    uint64_t max_frame_bytes;
} PunktfunkConfig;

// Reassembled access unit. `data`/`len` borrow session memory until the next
// `punktfunk_client_poll_frame` / `punktfunk_session_free` on this session.
typedef struct {
    const uint8_t *data;
    uintptr_t len;
    uint32_t frame_index;
    uint64_t pts_ns;
    uint32_t flags;
    // Reassembly-complete instant, ns since Unix epoch (`CLOCK_REALTIME`, same
    // clock as `pts_ns`). A stamp at poll return includes pre-decode queue wait.
    uint64_t received_ns;
} PunktfunkFrame;

// `#[repr(C)]` as `PunktfunkInputEvent`.
typedef struct {
    PunktfunkInputKind kind;
    uint8_t _pad[3];
    // keycode / button id / axis id, depending on `kind`.
    uint32_t code;
    // x / dx / abs-x / axis-value / scroll-delta, depending on `kind`.
    int32_t x;
    // y / dy / abs-y, depending on `kind`.
    int32_t y;
    // modifier bitmask or gamepad index.
    uint32_t flags;
} PunktfunkInputEvent;

// Session counters.
typedef struct {
    uint64_t frames_submitted;
    uint64_t frames_completed;
    uint64_t frames_dropped;
    uint64_t packets_sent;
    uint64_t packets_received;
    uint64_t packets_dropped;
    // Host send-path drops (`WouldBlock`). Distinct from recv-side `packets_dropped`.
    uint64_t packets_send_dropped;
    uint64_t fec_recovered_shards;
    uint64_t bytes_sent;
    uint64_t bytes_received;
} PunktfunkStats;

#if defined(PUNKTFUNK_FEATURE_QUIC)
// Growable connect options for [`punktfunk_connect_opts`]. Zero-init, set
// `struct_size = sizeof(PunktfunkConnectOpts)`, then the fields you mean.
// Zero = auto/unspecified (`audio_rate_hz = 0` is Opus; a non-zero pair is
// lossless). Append only; no tail padding (96/68-byte asserts); bump ABI.
typedef struct {
    // `sizeof(PunktfunkConnectOpts)` as this caller was compiled. Smaller than
    // the frozen minimum is rejected; a shorter prefix defaults the tail.
    uint32_t struct_size;
    // Required: NUL-terminated UTF-8 IP or hostname (the one non-nullable pointer here).
    const char *host;
    // Library id to auto-launch, or null ([`punktfunk_connect_ex4`]).
    const char *launch_id;
    // Null (trust on first use) or the host certificate's expected 32-byte SHA-256
    // ([`punktfunk_connect`]'s trust contract).
    const uint8_t *pin_sha256;
    // TLS client identity: both null (anonymous) or both NUL-terminated PEM
    // ([`punktfunk_generate_identity`]).
    const char *client_cert_pem;
    // See `client_cert_pem`.
    const char *client_key_pem;
    // Label this device knocks with, or null for the OS default
    // ([`punktfunk_connect_ex10`]).
    const char *device_name;
    // Requested mode ([`punktfunk_connect`]).
    uint32_t width;
    // See `width`.
    uint32_t height;
    // See `width`.
    uint32_t refresh_hz;
    // `PUNKTFUNK_COMPOSITOR_*`; `0`/unrecognized = auto ([`punktfunk_connect_ex`]).
    uint32_t compositor;
    // `PUNKTFUNK_GAMEPAD_*`; `0`/unrecognized = auto ([`punktfunk_connect_ex2`]).
    uint32_t gamepad;
    // Session wire budget in kbps; `0` = host default ([`punktfunk_connect_ex3`]).
    uint32_t bitrate_kbps;
    // Audio format ask; `0`/`0` = unspecified (Opus). An explicit pair — including
    // 48000/16 — is lossless and derives `PUNKTFUNK_CLIENT_CAP_AUDIO_HIRES`.
    uint32_t audio_rate_hz;
    // Connect timeout in milliseconds.
    uint32_t timeout_ms;
    // Required: the host's UDP port.
    uint16_t port;
    // `PUNKTFUNK_VIDEO_CAP_*` bits ([`punktfunk_connect_ex5`]).
    uint8_t video_caps;
    // Channel ask: 2 / 6 / 8; `0` = stereo ([`punktfunk_connect_ex6`]).
    uint8_t audio_channels;
    // See `audio_rate_hz`.
    uint8_t audio_bits;
    // `PUNKTFUNK_CODEC_*` bits the client can decode ([`punktfunk_connect_ex7`]).
    uint8_t video_codecs;
    // The one `PUNKTFUNK_CODEC_*` bit to prefer; `0` = host's choice
    // ([`punktfunk_connect_ex7`]).
    uint8_t preferred_codec;
    // `PUNKTFUNK_CLIENT_CAP_*` bits ([`punktfunk_connect_ex9`]).
    uint8_t client_caps;
    // Always `0`, ignored. Held so the struct keeps its v35 size.
    uint32_t reserved1;
    // Always `0`. Fills what would otherwise be tail padding: C leaves padding
    // unspecified even under `= {0}`, so the next appended field would read a
    // caller's garbage. Spend this before growing the struct again.
    uint32_t reserved0;
} PunktfunkConnectOpts;
#endif

